import{_ as a,o as d,c as e,ag as r}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"什么是数据点","description":"理解数据点的名称、路径、类型、来源、质量与时间，分清配置、当前值和历史记录。","frontmatter":{"title":"什么是数据点","description":"理解数据点的名称、路径、类型、来源、质量与时间，分清配置、当前值和历史记录。","status":"reviewed","kind":"explanation"},"headers":[],"relativePath":"zh/concepts/datapoints.md","filePath":"zh/核心概念/什么是数据点.md"}'),i={name:"zh/concepts/datapoints.md"};function l(o,t,h,n,s,p){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="什么是数据点" tabindex="-1">什么是数据点 <a class="header-anchor" href="#什么是数据点" aria-label="Permalink to &quot;什么是数据点&quot;">​</a></h1><p><strong>数据点是工程中供页面、计算和报警引用的一项数据定义。</strong> 它可以代表一个温度、一个开关状态，也可以代表一份查询结果。</p><p>可以把它理解成贴好名称的“数据接口”：使用者通过同一个点找到数据，不必在每个页面都重新配置设备地址或 SQL。</p><h2 id="一个温度数据点包含什么" tabindex="-1">一个温度数据点包含什么 <a class="header-anchor" href="#一个温度数据点包含什么" aria-label="Permalink to &quot;一个温度数据点包含什么&quot;">​</a></h2><p>下面只用于解释，不是平台已经接入的现场数据：</p><table tabindex="0"><thead><tr><th>内容</th><th>例子或含义</th></tr></thead><tbody><tr><td>名称</td><td>给人看的名称，例如“1 号线温度”</td></tr><tr><td>路径</td><td>供程序和配置准确引用的地址，从实际界面复制，不靠名称猜测</td></tr><tr><td>来源</td><td>温度从哪里来，例如工业变量、查询输出或计算输出</td></tr><tr><td>类型</td><td>值是什么形态，例如数值，而不是文本或完整对象</td></tr><tr><td>单位</td><td>数值的业务含义，例如摄氏温度</td></tr><tr><td>当前值</td><td>这次读取到或最近收到的结果，例如 25</td></tr><tr><td>质量</td><td>本次数据能否正常读取，还是失败、陈旧或尚未确认</td></tr><tr><td>时间</td><td>何时观察到或由来源产生，帮助判断是否仍适用</td></tr></tbody></table><p><strong>只有一个 25，不足以证明现场正常。</strong> 还要看它是不是预期来源、正确单位，以及质量和时间是否符合业务要求。</p><h2 id="数据点不只来自设备" tabindex="-1">数据点不只来自设备 <a class="header-anchor" href="#数据点不只来自设备" aria-label="Permalink to &quot;数据点不只来自设备&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>怎样成为工程中的数据</th></tr></thead><tbody><tr><td>工业设备</td><td>为采集连接配置变量，再形成相应点位</td></tr><tr><td>数据库</td><td>查询保存并配置输出，主动生成数据点</td></tr><tr><td>消息或接口</td><td>按订阅、请求或会话配置取值规则和输出</td></tr><tr><td>计算单元</td><td>输入已有数据，按逻辑形成新的输出点</td></tr></tbody></table><p>不是每一行数据库记录都自动变成一个点，也不是创建连接后所有字段都会自动可用。</p><p>有的点随新样本更新，有的在需要时读取或计算。存在点位定义，不代表它一直在采样、已经保存历史或已经部署运行。</p><h2 id="名称、路径和来源有什么区别" tabindex="-1">名称、路径和来源有什么区别 <a class="header-anchor" href="#名称、路径和来源有什么区别" aria-label="Permalink to &quot;名称、路径和来源有什么区别&quot;">​</a></h2><ul><li><strong>名称</strong>给人辨认；不同地方可能出现相似名称。</li><li><strong>路径</strong>用于准确引用，例如让页面或报警选中同一个点，应复制实际路径。</li><li><strong>来源</strong>决定点的取值规则。要改 SQL、消息解析或计算逻辑，应返回对应来源，不只改显示名称。</li></ul><p>修改输出 Key、类型或来源前，应检查哪些页面、计算和报警在使用它。删除定义或来源可能让引用失效，不是普通的“刷新数据”。</p><h2 id="类型为什么重要" tabindex="-1">类型为什么重要 <a class="header-anchor" href="#类型为什么重要" aria-label="Permalink to &quot;类型为什么重要&quot;">​</a></h2><p>“25”这个文字、数字 25 和包含温度的整份对象，对程序来说不是同一种数据。</p><ul><li>温度换算通常需要数值。</li><li>开关状态可能用布尔值，即 true/false。</li><li>表格可能需要完整数据集或数组。</li><li>报警应选择与条件兼容的类型，不能把一整份结果集直接与阈值比较。</li></ul><p>SQL 的“完整查询结果”和“提取单个字段”用途不同，见<a href="/induframe-docs/zh/guide/sql-datapoints.html">用 SQL 查询生成数据点</a>。</p><h2 id="有效-和-读取正常-不是一回事" tabindex="-1">“有效”和“读取正常”不是一回事 <a class="header-anchor" href="#有效-和-读取正常-不是一回事" aria-label="Permalink to &quot;“有效”和“读取正常”不是一回事&quot;">​</a></h2><p>点位列表的状态主要帮助判断配置是否有效、是否失效等；当前值的质量反映读取结果。</p><p>“读取正常”也不等于业务数值一定正确，仍要核对设备、单位和时间。“数据陈旧”不等于零，“读取失败”也不能当作正常的空值。</p><p>开发态默认值或配置预览用于开发检查，不是现场取数成功的证据。需要历史曲线时，还要安排实际样本与历史存储。</p><h2 id="到哪里查看和使用" tabindex="-1">到哪里查看和使用 <a class="header-anchor" href="#到哪里查看和使用" aria-label="Permalink to &quot;到哪里查看和使用&quot;">​</a></h2><ul><li>查看来源、当前值、质量、标签：<a href="/induframe-docs/zh/guide/datapoints.html">数据中心的数据点列表</a>。</li><li>页面选点、复制路径和角色调用权限：<a href="/induframe-docs/zh/guide/workspace-datapoints.html">应用开发的数据点管理</a>。</li><li>用点产生新结果：<a href="/induframe-docs/zh/guide/compute-datapoints.html">计算单元</a>。</li><li>根据点判断异常：<a href="/induframe-docs/zh/guide/point-alarms.html">报警配置</a>。</li><li>记录过去的样本：<a href="/induframe-docs/zh/guide/point-history.html">历史存储</a>。</li></ul><p>路径不是密码，也不是授权。知道点的路径，不代表一个工程用户就有权调用它。</p>',25)])])}const m=a(i,[["render",l]]);export{u as __pageData,m as default};
